from pathlib import Path
import json

BASE=Path('/Users/frankzhang/Desktop/投研助手/journal/four-type-validation-20261031')
cases={}
for key in ('asset','event','theme','actor'):
 p=BASE/key/'report.json'
 if p.is_file():
  cases[key]=json.loads(p.read_text())
  ledger=BASE/key/'claims.json'
  if ledger.is_file(): cases[key]['evidence_claims']=json.loads(ledger.read_text()).get('claims',[])
style='''
:root {color-scheme:light; --page:#fff;--ink:#000;--sub:#52514e;--rule:#deded9;--accent:#225eaa;--plot:#fcfcfb;--series:#2a78d6;--grid:#e1e0d9}
:root[data-theme="dark"]{color-scheme:dark;--page:#141414;--ink:#f0efec;--sub:#c3c2b7;--rule:#444;--accent:#8ab9ef;--plot:#1a1a19;--series:#3987e5;--grid:#2c2c2a}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){color-scheme:dark;--page:#141414;--ink:#f0efec;--sub:#c3c2b7;--rule:#444;--accent:#8ab9ef;--plot:#1a1a19;--series:#3987e5;--grid:#2c2c2a}}
*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font:17px/1.85 "PingFang SC",system-ui,sans-serif}button,a,summary{touch-action:manipulation}button{font:inherit;color:inherit;background:transparent;border:1px solid var(--rule);padding:7px 13px;cursor:pointer;border-radius:5px}button:hover{border-color:var(--accent)}a{color:var(--accent);text-underline-offset:4px}a:focus-visible,button:focus-visible,summary:focus-visible,[tabindex]:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.top{display:flex;align-items:center;justify-content:space-between;padding:18px 5vw;border-bottom:1px solid var(--rule);gap:16px}.brand{font-size:18px;font-weight:650}.tools{display:flex;gap:10px}.layout{max-width:1270px;margin:auto;display:grid;grid-template-columns:190px minmax(0,820px);gap:5vw;padding:38px 5vw 90px}nav{position:sticky;top:24px;align-self:start;display:grid;gap:10px}nav button{text-align:left;border:0;border-left:3px solid transparent;border-radius:0;font-size:16px}nav button[aria-selected="true"]{border-color:var(--accent);font-weight:650;color:var(--accent)}.meta{font-size:13px;color:var(--sub);overflow-wrap:anywhere}.title{font-size:clamp(27px,3.3vw,43px);line-height:1.35;font-weight:650;letter-spacing:-.025em;margin:12px 0 22px;max-width:22em}.question{color:var(--sub);font-size:16px}.answer{font-size:clamp(19px,2vw,23px);line-height:1.75;margin:24px 0 36px;max-width:35em}.finding{padding:22px 0 6px}.finding h2,section>h2{font-size:23px;line-height:1.45;margin:0 0 12px}.finding p{margin:0 0 12px;max-width:40em}.refs{font-size:12px;color:var(--sub);margin-left:6px}.divider{margin-top:32px;padding-top:26px;border-top:1px solid var(--rule)}.table-wrap{overflow:auto;margin:16px 0 26px;border-bottom:1px solid var(--rule)}table{border-collapse:collapse;min-width:540px;width:100%;font-size:14px;line-height:1.65}th,td{text-align:left;vertical-align:top;border-top:1px solid var(--rule);padding:12px 14px 12px 0;font-variant-numeric:tabular-nums}th{font-weight:650}caption{text-align:left;font-weight:600;padding-bottom:12px}.watch{display:grid;grid-template-columns:minmax(120px,1fr) 2fr;gap:20px;border-top:1px solid var(--rule);padding:15px 0}.watch p{margin:0}details{margin:22px 0}summary{cursor:pointer;font-weight:600}.sources li{margin:12px 0;overflow-wrap:anywhere;font-size:14px}.chart{background:var(--plot);padding:18px 12px;margin:30px 0}.chart svg{display:block;width:100%;height:auto;overflow:visible}.chart text{fill:var(--sub);font:12px system-ui,sans-serif}.readout{min-height:30px;font-size:14px;padding-left:8px}.chart-line{stroke:var(--series);stroke-width:2;fill:none;stroke-linecap:round;stroke-linejoin:round}.chart-dot{fill:var(--series);stroke:var(--plot);stroke-width:2}.axis{stroke:var(--grid);stroke-width:1}.cross{stroke:var(--sub);stroke-width:1;pointer-events:none}.foot{font-size:13px;color:var(--sub);margin-top:38px}.skip{position:absolute;left:-10000px}.skip:focus{left:20px;top:20px;z-index:10;background:var(--page)}
@media(max-width:760px){.layout{display:block;padding:18px 6vw 60px}nav{position:static;display:flex;flex-wrap:wrap;border-bottom:1px solid var(--rule);padding-bottom:20px;margin-bottom:26px;gap:2px}nav button{border-left:0;border-bottom:3px solid transparent;padding:6px 10px}.top{padding:16px 6vw}.brand{font-size:15px}.tools button{font-size:13px;padding:5px 8px}.watch{grid-template-columns:1fr;gap:4px}.title{font-size:29px}.answer{font-size:19px}}
@media print{.top,.tools,nav,.skip{display:none}.layout{display:block;max-width:none;padding:0}body{color:#000;background:#fff;font-size:11pt}details{display:block}details>*{display:block}.chart{break-inside:avoid}.title{font-size:26pt}a{color:inherit}table{min-width:0}section{break-inside:auto}}
'''
script=r'''
const reports=__DATA__;
const names={event:'事件定价',asset:'单一资产',theme:'行业主题',actor:'人物／机构'};
const main=document.getElementById('content');
function el(tag,text,cls,parent){const n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=String(text);if(cls)n.className=cls;if(parent)parent.append(n);return n}
function ref(p,ids){if(ids&&ids.length){const span=el('span',null,'refs',p);ids.forEach(id=>{const a=el('a','['+id+']',null,span);a.href='#claim-'+id;a.addEventListener('click',()=>{const target=document.getElementById('claim-'+id);if(target){target.closest('details').open=true;requestAnimationFrame(()=>target.scrollIntoView({block:'center'}))}})})}}
function str(x){if(x===null||x===undefined)return '—';if(typeof x==='object')return JSON.stringify(x);return String(x)}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
function table(t,parent){const wrap=el('div',null,'table-wrap',parent);const table=el('table',null,null,wrap);if(t.title)el('caption',t.title,null,table);const cols=t.columns||t.headers||[];const head=el('tr',null,null,el('thead',null,null,table));cols.forEach(c=>{const th=el('th',str(c),null,head);th.scope='col'});const body=el('tbody',null,null,table);(t.rows||[]).forEach(row=>{const tr=el('tr',null,null,body);(Array.isArray(row)?row:cols.map(k=>row[k])).forEach(c=>el('td',str(c),null,tr))});ref(wrap,t.claim_ids);if(t.note)el('p',t.note,'meta',wrap)}
function section(title){const s=el('section',null,'divider',main);el('h2',title,null,s);return s}
function drawChart(c){if(!c||!Array.isArray(c.rows)||c.rows.length<2)return;const rows=c.rows.filter(r=>Number.isFinite(Number(r.close)));if(rows.length<2)return;const box=el('section',null,'chart',main);el('h2',c.title||'收盘价',null,box);const NS='http://www.w3.org/2000/svg';const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 720 255');svg.setAttribute('role','img');svg.setAttribute('aria-label',c.title||'收盘价');box.append(svg);const read=el('div','鼠标移动或聚焦各日期读取价格','readout',box);read.setAttribute('aria-live','polite');const vals=rows.map(r=>Number(r.close)),lo=Math.floor(Math.min(...vals)/10)*10,hi=Math.ceil(Math.max(...vals)/10)*10;const x=i=>55+i/(rows.length-1)*640,y=v=>205-(v-lo)/(hi-lo||1)*165;
function mark(tag,attrs,text){const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text)n.textContent=text;svg.append(n);return n}
for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3,yy=y(v);mark('line',{x1:55,x2:695,y1:yy,y2:yy,class:'axis'});mark('text',{x:5,y:yy+4},v.toFixed(0))}
mark('polyline',{points:rows.map((r,i)=>x(i)+','+y(Number(r.close))).join(' '),class:'chart-line'});
const cross=mark('line',{x1:55,x2:55,y1:30,y2:210,class:'cross',visibility:'hidden'});
function show(i){read.textContent=rows[i].date+'  '+Number(rows[i].close).toFixed(2)+' 美元';cross.setAttribute('x1',x(i));cross.setAttribute('x2',x(i));cross.setAttribute('visibility','visible')}
rows.forEach((r,i)=>{if([0,rows.length-1,vals.indexOf(Math.max(...vals))].includes(i)){mark('circle',{cx:x(i),cy:y(Number(r.close)),r:4,class:'chart-dot'});mark('text',{x:x(i),y:232,'text-anchor':i===0?'start':i===rows.length-1?'end':'middle'},r.date.slice(5));}const hit=mark('rect',{x:x(i)-11,y:25,width:22,height:190,fill:'transparent',tabindex:0,'aria-label':r.date+' '+r.close+'美元'});hit.addEventListener('focus',()=>show(i));hit.addEventListener('pointermove',()=>show(i))});svg.addEventListener('pointermove',e=>{const b=svg.getBoundingClientRect();const xx=(e.clientX-b.left)/b.width*720;show(Math.max(0,Math.min(rows.length-1,Math.round((xx-55)/640*(rows.length-1)))))});const det=el('details',null,null,box);el('summary','逐日数据与口径',null,det);table({columns:['日期','收盘价（美元）'],rows:rows.map(r=>[r.date,Number(r.close).toFixed(2)])},det);el('p','收盘价格，不含股息。来源 '+(c.source||'见证据账本')+'。', 'meta',det)}
function render(key){const r=reports[key];if(!r)return;main.replaceChildren();document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.key===key)));el('p',names[key]+'案例', 'meta',main);el('h1',r.title||r.question,'title',main);el('p',r.question,'question',main);el('p','研究截点 '+r.as_of+'；'+(r.status==='partial'?'部分完成':str(r.status)),'meta',main);const ans=el('p',r.answer,'answer',main);ref(ans,r.answer_claim_ids);drawChart(r.chart);
(r.findings||[]).forEach(f=>{const s=el('section',null,'finding',main);el('h2',f.title,null,s);const p=el('p',f.text,null,s);ref(p,f.claim_ids)});
(r.tables||[]).forEach(t=>table(t,main));
if(r.alternatives?.length){const s=section('哪些解释值得继续检验');r.alternatives.forEach(a=>{el('h3',a.title,null,s);const p=el('p',a.text,null,s);ref(p,a.claim_ids)})}
if(r.watch?.length){const s=section('接下来观察什么');r.watch.forEach(w=>{const row=el('div',null,'watch',s);el('strong',w.signal,null,row);const p=el('p',w.meaning,null,row);ref(p,w.claim_ids)})}
const d=el('details',null,'divider',main);el('summary','研究范围、证据与缺口',null,d);(r.evidence_claims||[]).forEach(c=>{const item=el('p',null,null,d);item.id='claim-'+c.id;el('strong','['+c.id+'] ',null,item);el('span',c.text,null,item);el('span',' （'+c.type+'）','meta',item);if(c.basis?.length)el('span',' 依据 '+c.basis.join('、'),'meta',item);(c.sources||[]).forEach(s=>{const url=safeLink(s.url);if(url){const a=el('a',' '+(s.publisher||s.title||'来源'),null,item);a.href=url;a.target='_blank';a.rel='noopener noreferrer'}})});const ul=el('ul',null,null,d);(r.gaps||[]).forEach(g=>el('li',str(g),null,ul));const sl=el('ol',null,'sources',d);(r.sources||[]).forEach(s=>{const li=el('li',null,null,sl);const url=safeLink(s.url);if(url){const a=el('a',(s.id?s.id+' ':'')+(s.title||s.publisher||s.url),null,li);a.href=url;a.target='_blank';a.rel='noopener noreferrer'}else el('span',s.title||s.publisher,null,li);if(s.published_at)el('span','  '+s.published_at+(s.date_kind?'（'+s.date_kind+'）':''),'meta',li);if(s.quote)el('p',s.quote,'meta',li)});el('p','本轮为人工协调的方法开发案例。证据字段检查、研究判断与前瞻效果分别评价；详细记录随下载包保存。','foot',main);document.title=(r.title||'研究案例')+' | 投研助手';history.replaceState(null,'','#'+key)}
const nav=document.querySelector('nav');Object.keys(names).filter(k=>reports[k]).forEach(key=>{const b=el('button',names[key],null,nav);b.dataset.key=key;b.setAttribute('role','tab');b.addEventListener('click',()=>render(key))});document.getElementById('theme').addEventListener('click',()=>{const d=document.documentElement;const dark=d.dataset.theme?d.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;d.dataset.theme=dark?'light':'dark'});document.getElementById('print').addEventListener('click',()=>window.print());render(reports[location.hash.slice(1)]?location.hash.slice(1):(reports.event?'event':Object.keys(reports)[0]));
'''
script=script.replace('__DATA__',json.dumps(cases,ensure_ascii=False).replace('<','\\u003c'))
html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>四类投研案例</title><style>'+style+'</style></head><body><a class="skip" href="#content">跳到研究正文</a><header class="top"><div class="brand">投研助手 / 四类案例验证</div><div class="tools"><button id="theme">切换明暗</button><button id="print">打印本例</button></div></header><div class="layout"><nav role="tablist" aria-label="研究案例"></nav><main id="content" tabindex="-1"></main></div><script>'+script+'</script></body></html>'
(BASE/'index.html').write_text(html)
print(json.dumps({'cases':list(cases),'output':str(BASE/'index.html'),'bytes':len(html.encode())},ensure_ascii=False))
